const seedData=JSON.parse(document.getElementById('privateSeed').textContent);
FinanceCore.validate(seedData);
const storageKey='familyPrivateSicoob20261015v2';
let state=structuredClone(seedData), storageAvailable=true;
try {const saved=localStorage.getItem(storageKey);if(saved){const parsed=JSON.parse(saved);FinanceCore.validate(parsed);state=parsed;}}catch(e){storageAvailable=false;}
let activeTab='overview',cardId='master',holderFilter='',cardSearch='',bankSearch='',bankMode='realized',investmentDate='2026-10-14',investmentSearch='',editingRecord=null;
let chartPeriod='week',chartFuture=true,chartHorizon=90;
const categories=['A revisar','Moradia','Supermercado','Alimentação fora de casa','Combustível','Saúde','Educação','Vestuário e cuidados','Viagens','Assinaturas e serviços digitais','Publicidade','Pets','Seguros','Documentação','Tarifas e encargos','Transferência entre contas próprias','Transferência familiar','Integralização de capital','Saque para carteira','Outros'];
const money=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),num=n=>n===null||n===undefined?'—':Number(n).toLocaleString('pt-BR',{maximumFractionDigits:8}),br=s=>s?s.split('-').reverse().join('/'):'Não informada',sum=FinanceCore.sum;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const signed=v=>`<span class="${v<0?'negative':'positive'}">${v<0?'−':'+'}${money(Math.abs(v))}</span>`;
const cardAmount=v=>`<span class="${v>0?'negative':'positive'}">${v<0?'−':''}${money(Math.abs(v))}</span>`;
const source=s=>s?`<small class="source">${esc(s.file||'')}${s.page?' · página '+s.page:''}${s.sheet?' · '+esc(s.sheet):''}${s.row?' · linha '+s.row:''}</small>`:'<small>Registro manual</small>';
const table=(headers,rows,cls='')=>`<div class="table-wrap"><table class="${cls}"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}" class="empty">Nenhum registro neste filtro.</td></tr>`}</tbody></table></div>`;
const kpi=(label,value,note)=>`<article class="card"><small>${label}</small><div class="big">${value}</div><small>${note}</small></article>`;
const categoryButton=(t,ledger)=>`<button class="category" data-review="${esc(t.id)}" data-ledger="${ledger}">${esc(t.category)}${t.categoryConfirmed?' ✓':t.categorySource==='learned'?' · reconhecida':' · revisar'}</button>${t.note?`<small>${esc(t.note)}</small>`:''}${t.recognitionSuggestion?`<small>Sugestão: ${esc(t.recognitionSuggestion.category)}. Confirme o beneficiário.</small>`:''}`;
function save(){Recognition.refresh(state);try{localStorage.setItem(storageKey,JSON.stringify(state));storageAvailable=true;}catch(e){storageAvailable=false;}renderStorage();}
function renderStorage(){document.getElementById('storageWarning').innerHTML=storageAvailable?'':`<div class="note">Este navegador não está salvando alterações. Use “Salvar cópia” antes de fechar.</div>`;}
function go(tab){activeTab=tab;render();window.scrollTo({top:0});}
function render(){
 const tabs=[['overview','Visão geral'],['bank','Conta corrente'],['cards','Cartões e faturas'],['investments','Investimentos'],['income','Proventos'],['future','Próximos pagamentos'],['learning','Aprendizado'],['audit','Validação']];
 document.getElementById('navigation').innerHTML=tabs.map(([id,label])=>`<button data-tab="${id}" class="${id===activeTab?'active':''}" ${id===activeTab?'aria-current="page"':''}>${label}</button>`).join('');
 document.getElementById('content').innerHTML=({overview:overviewView,bank:bankView,cards:cardsView,investments:investmentsView,income:incomeView,future:futureView,learning:learningView,audit:auditView}[activeTab])();
 renderStorage();
}
function overviewView(){
 const account=state.accounts[0],bal=FinanceCore.cashBalance(account,state.bankTransactions,state.asOf),current=state.investmentSnapshots.at(-1),master=state.cards.find(c=>c.id==='master');
 const realized=state.bankTransactions.filter(t=>!t.future),debits=-sum(realized.filter(t=>t.value<0)),credits=sum(realized.filter(t=>t.value>0));
 return `<div class="grid">${kpi('Saldo próprio em conta',money(bal),'Sicoob · posição em '+br(state.asOf))}${kpi('Carteira de investimentos',money(current.total),current.positions.length+' posições · '+br(current.date))}${kpi('Fatura Mastercard de outubro','Paga',money(master.invoiceTotal)+' · débito em '+br(master.paidDate))}</div>
 <div class="two"><article class="card"><h2>Conta e crédito separados</h2><dl><dt>Cheque especial contratado</dt><dd>${money(account.overdraftLimit)}</dd><dt>Disponível incluindo cheque especial</dt><dd>${money(bal+account.overdraftLimit)}</dd><dt>Crédito utilizado nesta posição</dt><dd>${money(Math.max(0,-bal))}</dd></dl><p class="muted">O limite de crédito não compõe seu saldo próprio nem seu patrimônio.</p><button data-tab="bank">Ver os ${realized.length} movimentos</button></article>
 <article class="card"><h2>Entradas e saídas da conta</h2><small>01/10 a 15/10/2026 · visão de caixa</small><dl><dt>Saldo anterior em 30/09</dt><dd>${money(account.openingBalance)}</dd><dt>Entradas</dt><dd class="positive">${money(credits)}</dd><dt>Saídas, incluindo pagamento do cartão</dt><dd class="negative">${money(debits)}</dd><dt>Saldo em 15/10</dt><dd><b>${money(bal)}</b></dd></dl></article></div>
 ${cashChartView()}<article class="card"><h2>Aprendizado das suas revisões</h2><p>${state.recognitionEvidence.length} revisões aproveitadas em ${state.recognitionRules.length} regras locais. Novos lançamentos identificáveis recebem a categoria aprendida; Pix e boletos genéricos continuam sujeitos a conferência.</p><button data-tab="learning">Ver o que o sistema aprendeu</button></article><article class="card"><h2>Importação conferida</h2><p>${state.checks.length} conferências de totais, saldos diários e faturas passaram. As categorias sugeridas ainda precisam de revisão.</p><div class="row"><span class="good">Pagamento do Mastercard vinculado à conta</span><button data-tab="audit">Ver a validação e os pontos de atenção</button></div></article><div class="footer">Versão local com dados pessoais. Não publicada no GitHub Pages. Sem sincronização entre dispositivos.</div>`;
}
function cashChartView(){
 const end=new Date(state.asOf+'T00:00:00Z');end.setUTCDate(end.getUTCDate()+chartHorizon);
 const endDate=end.toISOString().slice(0,10),forecastRows=chartFuture?Installments.forecastRows(state):state.bankTransactions;
 const series=FinanceCore.cashSeries(state.accounts[0],forecastRows,state.asOf,chartPeriod,chartFuture,endDate);
 const left=85,right=930,top=24,bottom=245,width=(right-left)/Math.max(1,series.length);
 const min=Math.min(0,...series.map(g=>g.balance)),max=Math.max(1,...series.flatMap(g=>[g.balance,g.credit,g.debit])),span=max-min;
 const y=v=>bottom-(v-min)/span*(bottom-top),zero=y(0),compact=v=>Math.abs(v)>=1000?(v/1000).toLocaleString('pt-BR',{maximumFractionDigits:1})+' mil':num(v);
 let parts=[];
 for(let n=0;n<=4;n++){const v=min+span*n/4,py=y(v);parts.push(`<line x1="${left}" y1="${py}" x2="${right}" y2="${py}" stroke="#e0e7ef"/><text x="${left-12}" y="${py+4}" text-anchor="end">${esc(compact(v))}</text>`);}
 let actual=[],future=[];
 series.forEach((g,i)=>{const x=left+(i+.5)*width,bw=Math.min(24,width*.29),label=br(g.from)+(g.to!==g.from?' a '+br(g.to):'');
   parts.push(`<rect x="${x-bw-2}" y="${y(g.credit)}" width="${bw}" height="${Math.max(0,zero-y(g.credit))}" rx="2" fill="#4175bf" opacity="${g.forecast?.5:1}"><title>${esc(label)} · Créditos: ${money(g.credit)}</title></rect><rect x="${x+2}" y="${y(g.debit)}" width="${bw}" height="${Math.max(0,zero-y(g.debit))}" rx="2" fill="#c94d59" opacity="${g.forecast?.5:1}"><title>${esc(label)} · Débitos: ${money(g.debit)}</title></rect>`);
   (g.forecast?future:actual).push(`${x},${y(g.balance)}`);
   if(i%Math.max(1,Math.ceil(series.length/9))===0||i===series.length-1)parts.push(`<text x="${x}" y="277" text-anchor="middle">${g.from.slice(8)}/${g.from.slice(5,7)}</text>`);
 });
 if(future.length&&actual.length)future.unshift(actual.at(-1));
 parts.push(`<polyline points="${actual.join(' ')}" fill="none" stroke="#2b815a" stroke-width="3"/><polyline points="${future.join(' ')}" fill="none" stroke="#d28b26" stroke-width="3" stroke-dasharray="7 5"/>`);
 series.forEach((g,i)=>parts.push(`<circle cx="${left+(i+.5)*width}" cy="${y(g.balance)}" r="4" fill="${g.forecast?'#d28b26':'#2b815a'}"><title>${br(g.to)} · ${g.forecast?'Saldo previsto':'Saldo realizado'}: ${money(g.balance)}</title></circle>`));
 return `<article class="card" id="cashChartCard"><div class="row"><h2>Créditos, débitos e saldo</h2><div class="chart-periods">${[['day','Dia'],['week','Semana'],['fortnight','Quinzena'],['month','Mês']].map(([id,name])=>`<button data-chart-period="${id}" class="${chartPeriod===id?'active':''}" aria-pressed="${chartPeriod===id}">${name}</button>`).join('')}</div></div><div class="row"><small>Conta corrente · valores em R$ · ${series.length?br(series[0].from)+' a '+br(series.at(-1).to):'Sem movimentos'}</small><label class="chart-toggle"><input type="checkbox" id="chartFuture" ${chartFuture?'checked':''}> Mostrar previsão futura</label><label class="chart-toggle">Horizonte<select id="chartHorizon">${[30,90,180,365].map(n=>`<option value="${n}" ${chartHorizon===n?'selected':''}>${n} dias</option>`).join('')}</select></label></div><div class="chart-scroll"><svg id="cashChart" viewBox="0 0 960 300" role="img" aria-label="Gráfico de créditos, débitos e saldo da conta corrente"><title>Créditos, débitos e saldo da conta corrente</title><g font-family="system-ui,sans-serif" font-size="13" fill="#63758b">${parts.join('')}</g></svg></div><div class="chart-legend"><span><i style="background:#4175bf"></i>Créditos</span><span><i style="background:#c94d59"></i>Débitos</span><span><i style="background:#2b815a"></i>Saldo realizado</span>${chartFuture?'<span><i style="background:#d28b26"></i>Saldo previsto (tracejado)</span>':''}</div><p class="muted">Previsão inclui agendamentos bancários, parcelas futuras dos cartões e anuidades estimadas. Não inclui receitas, novas compras ou despesas ainda não cadastradas. Não cria lançamentos na conta nem considera cheque especial como saldo. Linha tracejada: saldo previsto.</p>${chartFuture?`<p><b>Saldo previsto em ${br(series.at(-1).to)}: <span class="${series.at(-1).balance<0?'negative':'positive'}">${money(series.at(-1).balance)}</span></b><small> · cenário com as movimentações cadastradas</small></p>`:''}<details><summary>Ver valores do gráfico</summary>${table(['Período','Créditos','Débitos','Saldo ao final','Situação'],series.map(g=>`<tr><td>${br(g.from)}${g.to!==g.from?' a '+br(g.to):''}</td><td class="num">${money(g.credit)}</td><td class="num">${money(g.debit)}</td><td class="num">${money(g.balance)}</td><td>${g.forecast?'Previsto':'Realizado'}</td></tr>`))}</details></article>`;
}
function bankView(){
 const a=state.accounts[0],bal=FinanceCore.cashBalance(a,state.bankTransactions,state.asOf);
 const rows=state.bankTransactions.filter(t=>(bankMode==='all'||(bankMode==='future'?t.future:!t.future))&&[t.description,...t.details].join(' ').toLowerCase().includes(bankSearch.toLowerCase()));
 let running=a.openingBalance;const balances=new Map();for(const t of state.bankTransactions.filter(t=>!t.future)){running=Math.round((running+t.value)*100)/100;balances.set(t.id,running);}
 return `<div class="row"><h2>Conta corrente Sicoob</h2><div><button id="newStatement">Importar lançamentos</button> <button class="primary" id="newBank">+ Novo movimento</button></div></div><div class="grid">${kpi('Saldo próprio',money(bal),'Até '+br(state.asOf))}${kpi('Cheque especial',money(a.overdraftLimit),'Limite contratado, separado do saldo')}${kpi('Disponível com crédito',money(a.availableIncludingCredit),'Valor informado no extrato')}</div>
 <article class="card"><details><summary>Dados da conta, limites e encargos</summary><dl><dt>Cooperativa / conta</dt><dd>${esc(a.cooperative)} / ${esc(a.accountNumber)}</dd><dt>Período do extrato</dt><dd>01/10 a 15/10/2026</dd><dt>Vencimento do cheque especial</dt><dd>${br(a.overdraftMaturity)}</dd><dt>Taxa de cheque especial</dt><dd>${num(a.overdraftMonthlyRate)}% a.m.</dd><dt>CET</dt><dd>${num(a.cetMonthly)}% a.m. / ${num(a.cetAnnual)}% a.a.</dd><dt>Crédito pessoal disponível (limite)</dt><dd>${money(a.personalCreditLimit)}</dd><dt>Parcela máxima disponível</dt><dd>${money(a.maxPersonalCreditPayment)}</dd><dt>Bloqueios e encargos provisionados</dt><dd>R$ 0,00 no extrato</dd></dl></details>
 <div class="toolbar"><label>Movimentos<select id="bankMode"><option value="realized" ${bankMode==='realized'?'selected':''}>Realizados</option><option value="future" ${bankMode==='future'?'selected':''}>Agendados</option><option value="all" ${bankMode==='all'?'selected':''}>Todos</option></select></label><label>Buscar<input id="bankSearch" value="${esc(bankSearch)}" placeholder="Histórico ou favorecido"></label></div><p class="muted">${rows.length} registros no filtro. Histórico do banco preservado; categoria é sugestão até sua revisão.</p>
 ${table(['Data','Histórico e detalhes','Categoria','Valor','Saldo próprio após movimento'],rows.map(t=>`<tr><td>${br(t.date)}${t.future?'<small>Agendado</small>':''}</td><td>${esc(t.description)}${t.kind==='card_payment'?'<small class="good">Pagamento vinculado à fatura Mastercard</small>':''}<details><summary>Detalhes do extrato</summary><p>${t.details.map(esc).join('<br>')}</p>${source(t.source)}</details></td><td>${categoryButton(t,'bank')}</td><td class="num">${signed(t.value)}</td><td class="num">${t.future?'—':money(balances.get(t.id))}</td></tr>`))}
 <div class="note">O débito do Mastercard de ${money(state.cards.find(c=>c.id==='master').invoiceTotal)} reduz o caixa. O detalhamento das compras permanece em Cartões e faturas e não é lançado de novo na conta.</div></article>`;
}
function cardsView(){
 const c=state.cards.find(c=>c.id===cardId),all=state.cardTransactions.filter(t=>t.cardId===cardId),spend=all.filter(t=>t.kind!=='payment'),holders=[...new Set(all.filter(t=>t.last4).map(t=>t.last4))];
 const filtered=all.filter(t=>(!holderFilter||(holderFilter==='operations'?!t.last4:t.last4===holderFilter))&&[t.description,t.city,t.holder,t.rawDate].join(' ').toLowerCase().includes(cardSearch.toLowerCase()));
 const summary=holders.map(h=>{const rs=all.filter(t=>t.last4===h);return `<tr><td>${esc(rs[0].holder)}</td><td>${h}</td><td>${rs.length}</td><td class="num">${money(sum(rs))}</td></tr>`;});
 const grouped={};for(const t of spend)grouped[t.category]=(grouped[t.category]||0)+t.value;
 const categoriesTable=table(['Categoria sugerida','Compras, estornos e encargos líquidos'],Object.entries(grouped).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<tr><td>${esc(k)}</td><td class="num">${money(v)}</td></tr>`));
 return `<div class="toolbar"><label>Cartão<select id="cardSelect">${state.cards.map(x=>`<option value="${x.id}" ${x.id===cardId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label></div><div class="row"><h2>${esc(c.name)}</h2><span class="good">${c.invoiceTotal===0?'Fatura zerada':'Paga em '+br(c.paidDate)}</span></div><p class="muted">Referência ${esc(c.period)} · fechamento em 01/10/2026 · vencimento em ${br(c.dueDate)}</p>
 <div class="grid">${kpi('Fatura de outubro',money(c.invoiceTotal),'Compras e parcelas da referência setembro')}${kpi('Limite de compras',money(c.purchaseLimit),'Limite, sem compor seu patrimônio')}${kpi('Disponível para compras',money(c.availableLimit),'Consulta do emissor em 15/10/2026')}</div>
 ${installmentsView(c)}<article class="card"><div class="row"><h3>Gastos separados da conta corrente</h3><small>${all.length} registros importados</small></div><p>${c.invoiceTotal?`O pagamento de ${money(c.invoiceTotal)} está vinculado ao débito bancário de 13/10. As compras e os estornos abaixo são analisados nesta fatura.`:`A anuidade de ${money(c.nextFee)} foi integralmente compensada por desconto. O pagamento de ${money(c.openingInvoice)} em setembro liquidou o saldo anterior; não foi criada saída em outubro.`}</p>
 <details><summary>Composição da fatura e limites</summary><dl><dt>Saldo da fatura anterior</dt><dd>${money(c.openingInvoice)}</dd><dt>Movimentos deste documento (inclui pagamento anterior)</dt><dd>${money(sum(all))}</dd><dt>Total conferido</dt><dd>${money(FinanceCore.invoiceTotal(c,all))}</dd><dt>Gastos/estornos/encargos desta referência</dt><dd>${money(FinanceCore.cardSpending(all))}</dd><dt>Limite utilizado no momento da consulta</dt><dd>${money(c.usedLimit)}</dd><dt>Limite de saque</dt><dd>${money(c.cashLimit)}</dd></dl><p class="muted">Valores de limite são da consulta do emissor, não uma recomposição a partir desta fatura. Cenários de pagamento mínimo/rotativo são simulações do documento e não foram lançados como dívida contratada.</p></details>
 ${holders.length?`<details><summary>Resumo por portador e final do cartão</summary>${table(['Portador','Final','Registros','Líquido na fatura'],summary)}</details>`:''}
 <details><summary>Análise por categoria sugerida</summary>${categoriesTable}<p class="muted">Categorias sugeridas pelo nome do estabelecimento; revise cada lançamento para confirmar.</p></details>
 <div class="toolbar"><label>Final do cartão<select id="holderFilter"><option value="">Todos os portadores</option><option value="operations" ${holderFilter==='operations'?'selected':''}>Movimentações da conta cartão</option>${holders.map(h=>`<option value="${h}" ${holderFilter===h?'selected':''}>${h} · ${esc(all.find(t=>t.last4===h).holder)}</option>`).join('')}</select></label><label>Buscar lançamento<input id="cardSearch" value="${esc(cardSearch)}" placeholder="Estabelecimento, cidade ou portador"></label></div><p class="muted">${filtered.length} registros no filtro · datas originais como impressas. O ano de compras antigas não foi presumido.</p>
 ${table(['Data original','Descrição','Portador / parcela','Categoria','Valor'],filtered.map(t=>`<tr><td>${esc(t.rawDate)}${t.kind==='payment'?'<small>Pagamento anterior</small>':''}</td><td>${esc(t.description)}<small>${esc(t.city)}</small><details><summary>Registro original</summary><p>${esc(t.raw).replace(/\n/g,'<br>')}</p>${source(t.source)}${t.reviewNote?`<p>${esc(t.reviewNote)}</p>`:''}</details></td><td>${esc(t.holder)}${t.last4?'<small>Final '+t.last4+'</small>':''}${t.installment?`<small>Parcela ${t.installment.current}/${t.installment.total}</small>`:''}</td><td>${categoryButton(t,'card')}</td><td class="num">${cardAmount(t.value)}</td></tr>`))}</article>
 <article class="card"><h3>Próxima fatura, ainda não fechada</h3><dl><dt>Saldo preliminar informado pelo emissor</dt><dd>${money(c.nextInvoicePreview)}</dd>${c.nextInstallments?`<dt>Parcelas para a próxima fatura</dt><dd>${money(c.nextInstallments)}</dd><dt>Saldo de todos os parcelamentos futuros</dt><dd>${money(c.futureInstallmentBalance)}</dd>`:''}<dt>Tarifa informada para a próxima fatura</dt><dd>${money(c.nextFee)}</dd></dl><p class="muted">Esses campos têm bases distintas e não são somados entre si. A próxima fatura fechada será necessária para confirmar o valor a pagar. Vencimento cadastrado: dia ${c.dueDay}.</p></article>`;
}
function investmentsView(){
 const s=state.investmentSnapshots.find(s=>s.date===investmentDate)||state.investmentSnapshots.at(-1),previous=state.investmentSnapshots[0];
 const filtered=s.positions.filter(p=>[p.name,p.institution,p.code,p.type].join(' ').toLowerCase().includes(investmentSearch.toLowerCase()));
 const types={};for(const p of s.positions)types[p.type]=(types[p.type]||0)+p.value;
 return `<div class="row"><h2>Carteira de investimentos</h2><label>Posição<select id="investmentDate">${state.investmentSnapshots.map(x=>`<option value="${x.date}" ${x.date===s.date?'selected':''}>${br(x.date)}${x.date===state.investmentAsOf?' · atual':''}</option>`).join('')}</select></label></div><p class="muted">Exportação em 15/10. Data-base atual de 14/10 conforme sua informação. Setembro é o histórico mensal.</p><div class="grid">${kpi('Patrimônio aplicado',money(s.total),s.positions.length+' posições, incluindo ativos cedidos')}${kpi('Posição de setembro',money(previous.total),'Histórico preservado em separado')}${kpi('CDI oficial','<span id="cdiValue">Consultando…</span>','<span id="cdiReference">Banco Central · série 4389</span>')}</div>
 <article class="card"><details><summary>Distribuição da carteira e comparação</summary><div class="allocation">${Object.entries(types).map(([type,v])=>`<span>${esc(type)}</span><strong>${money(v)}</strong>`).join('')}</div><p>Variação de posição entre setembro e 14/10: ${money(state.investmentSnapshots.at(-1).total-previous.total)}. Não representa rentabilidade calculada: movimentações completas de investimento não foram fornecidas.</p></details><div class="note">O extrato informa DI para CDB/LCA, mas não informa o percentual contratado do CDI. Não há projeção automática sem essa taxa. Ações emprestadas como doador continuam sendo ativos, em posição separada da custódia.</div>
 <div class="toolbar"><label>Buscar investimento<input id="investmentSearch" value="${esc(investmentSearch)}" placeholder="Produto, instituição, código ou tipo"></label></div>
 ${table(['Aplicação','Instituição','Quantidade','Posição bruta','Detalhes'],filtered.map(p=>`<tr><td><b>${esc(p.name)}</b><small>${esc(p.type)}</small><small>${esc(p.code)}</small></td><td>${esc(p.institution)}${p.account?'<small>Conta de custódia '+esc(p.account)+'</small>':''}</td><td class="num">${num(p.quantity)}</td><td class="num">${money(p.value)}</td><td><details><summary>Ver posição</summary><p>${p.price!==null?'Preço informado: '+num(p.price)+'<br>':''}${p.maturity?'Vencimento: '+br(p.maturity)+'<br>':''}${p.issueDate?'Emissão (não é data de compra): '+br(p.issueDate)+'<br>':''}${p.index?'Indexador: '+esc(p.index)+'<br>':''}${p.netValue?'Valor líquido informado: '+money(p.netValue)+'<br>':''}${p.principal?'Valor aplicado informado: '+money(p.principal)+'<br>':''}${p.contract?'Contrato de doação: '+esc(p.contract)+'<br>':''}Taxa contratada: não informada</p>${source(p.source)}</details></td></tr>`))}</article>`;
}
function installmentsView(card){
 const plan=Installments.schedule(card,state.cardTransactions),allPlans=state.cards.map(c=>({card:c,plan:Installments.schedule(c,state.cardTransactions)}));
 const dates=[...new Set(allPlans.flatMap(p=>p.plan.months.map(m=>m.due)))].sort();
 const monthLabel=date=>new Date(date+'T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'});
 const totalAll=Math.round(allPlans.reduce((s,p)=>s+Math.round(p.plan.total*100),0))/100;
 const byHolder=new Map();for(const item of plan.items.filter(i=>i.kind!=='fee')){const key=item.holder+'|'+item.last4;if(!byHolder.has(key))byHolder.set(key,{holder:item.holder,last4:item.last4,total:0});byHolder.get(key).total+=Math.round(item.balance*100);}
 const first=plan.months[0];
 return `<article class="card" id="installmentSummary"><h2>Parcelas a vencer</h2><p class="muted">${esc(card.name)} · após a fatura com vencimento em ${br(card.dueDate)}, já liquidada. Vencimentos contratuais no dia ${card.dueDay}; sem ajuste de dias não úteis.</p><div class="grid">${kpi('Compras parceladas restantes',money(plan.purchaseTotal),'Líquido dos estornos parcelados')}${kpi('Anuidades futuras estimadas',money(plan.feeTotal),'Valor bruto, sem presumir novos descontos')}${kpi('Próximo mês: parcelas + anuidade',money(first?.total||0),first?br(first.due)+' · estimativa':'Sem parcelas de compra')}</div>
 ${plan.reportedDifference===0?'<span class="good">Saldo de compras parceladas confere com a fatura</span>':plan.reportedDifference!==null?`<div class="note">Diferença de ${money(plan.reportedDifference)} em relação ao saldo parcelado informado pelo emissor. Conferir antes de tratar a projeção como compromisso fechado.</div>`:''}
 ${table(['Mês / vencimento','Parcelas de compras','Estornos parcelados','Compras líquidas','Anuidade estimada','Total estimado'],plan.months.map(m=>`<tr><td><b>${esc(monthLabel(m.due))}</b><small>${br(m.due)}</small></td><td class="num">${money(m.purchases)}</td><td class="num">−${money(m.credits)}</td><td class="num">${money(m.netPurchases)}</td><td class="num">${money(m.fees)}</td><td class="num"><b>${money(m.total)}</b></td></tr>`))}
 <p>Compras líquidas: <b>${money(plan.purchaseTotal)}</b>. Anuidades estimadas: <b>${money(plan.feeTotal)}</b>. Total deste cartão: <b>${money(plan.total)}</b>.</p>
 <details><summary>Separar por portador e final do cartão</summary>${table(['Portador','Final','Compras parceladas líquidas a vencer'],[...byHolder.values()].map(h=>`<tr><td>${esc(h.holder)}</td><td>${esc(h.last4)}</td><td class="num">${money(h.total/100)}</td></tr>`))}</details>
 <details><summary>Ver cada compra e suas parcelas restantes</summary>${table(['Compra / portador','Parcela nesta fatura','Faltam','Valor por parcela','Saldo restante','Último vencimento'],plan.items.map(i=>`<tr><td>${esc(i.description)}<small>${esc(i.holder)}${i.last4?' · final '+esc(i.last4):''}</small>${i.kind==='fee'?'<small>Anuidade bruta estimada</small>':i.kind==='refund'?'<small>Estorno parcelado</small>':''}${source(i.source)}</td><td>${i.current}/${i.total}</td><td>${i.remaining}</td><td class="num">${money(i.unit)}</td><td class="num">${money(i.balance)}</td><td>${br(i.lastDue)}</td></tr>`))}</details>
 <details><summary>Resumo mensal de todos os cartões</summary>${table(['Vencimento',...allPlans.map(p=>esc(p.card.name)),'Total estimado'],dates.map(d=>{const amounts=allPlans.map(p=>p.plan.months.find(m=>m.due===d)?.total||0);return `<tr><td>${br(d)}</td>${amounts.map(a=>`<td class="num">${money(a)}</td>`).join('')}<td class="num"><b>${money(amounts.reduce((s,a)=>s+Math.round(a*100),0)/100)}</b></td></tr>`;}))}<p>Total de parcelas e anuidades brutas dos cartões: <b>${money(totalAll)}</b>.</p></details>
 <div class="note">Projeção das parcelas remanescentes desta fatura, sem repetir a parcela de outubro já paga. O estorno parcelado do hotel compensa a compra correspondente nos meses seguintes. Novas compras, cobranças recorrentes à vista, juros e eventuais alterações/cancelamentos não entram nesta projeção. Descontos de anuidade futuros não foram presumidos.</div>
 ${plan.nextFieldDifference?`<details><summary>Conferência dos campos da próxima fatura</summary><p>O emissor mostra ${money(card.nextInstallments)} no campo “parcelas para a próxima fatura”. Pelas parcelas individualizadas, as compras líquidas do primeiro mês somam ${money(first.netPurchases)} — diferença de ${money(plan.nextFieldDifference)}. Com a anuidade estimada de ${money(first.fees)}, o total de ${money(first.total)} ${Math.round(first.total*100)===Math.round(card.nextInvoicePreview*100)?'coincide com o saldo preliminar da próxima fatura':'difere do saldo preliminar de '+money(card.nextInvoicePreview)}. Mantivemos os campos separados para não somar compromissos duas vezes.</p></details>`:''}
 ${plan.feeRoundingDifference?`<p class="muted">Arredondamento da anuidade: diferença de ${money(plan.feeRoundingDifference)} entre a projeção por parcela e o saldo de anuidades informado pelo emissor.</p>`:''}</article>`;
}
function incomeView(){
 const total=sum(state.investmentIncome),reimbursements=sum(state.investmentCrossReferences);
 return `<h2>Proventos de investimentos</h2><div class="grid">${kpi('Recebidos em setembro',money(total),state.investmentIncome.length+' registros líquidos')}${kpi('Reembolsos já incluídos',money(reimbursements),'Quatro referências, sem nova receita')}${kpi('Conciliação bancária','Pendente','Extrato da conta começa em outubro')}</div><article class="card"><p>Registros da B3 mantidos separados dos créditos da conta corrente e da posição dos ativos. Os preços unitários impressos são arredondados; o valor líquido de cada registro é a referência.</p>${table(['Pagamento','Produto / evento','Instituição','Valor líquido'],state.investmentIncome.map(t=>`<tr><td>${br(t.date)}</td><td>${esc(t.product)}<small>${esc(t.event)}</small>${source(t.source)}</td><td>${esc(t.institution)}</td><td class="num">${money(t.value)}</td></tr>`))}</article>`;
}
function futureView(){
 const future=state.bankTransactions.filter(t=>t.future),bal=FinanceCore.cashBalance(state.accounts[0],state.bankTransactions,state.asOf),committed=-sum(future);
 return `<h2>Próximos pagamentos</h2><div class="grid">${kpi('Saldo de partida',money(bal),'Posição bancária em 15/10')}${kpi('Agendados no extrato',money(committed),'Dois títulos em 05/11')}${kpi('Saldo após os agendados',money(bal-committed),'Cenário sem novas entradas ou saídas')}</div><article class="card"><h3>Agendamentos e movimentos futuros</h3>${table(['Data','Histórico','Documento','Saída'],future.map(t=>`<tr><td>${br(t.date)}</td><td>${esc(t.description)}</td><td>${t.details.map(esc).join('<br>')}</td><td class="num">${money(-t.value)}</td></tr>`))}<p class="muted">O cenário acima considera somente os dois agendamentos fornecidos, sem presumir salários, recorrências ou novas despesas.</p></article><article class="card"><h3>Cartões: prévias separadas dos agendamentos</h3>${table(['Cartão','Próximo vencimento cadastrado','Prévia do emissor','Situação'],state.cards.map(c=>`<tr><td>${esc(c.name)}</td><td>Dia ${c.dueDay} de novembro</td><td class="num">${money(c.nextInvoicePreview)}</td><td>Não fechada; valor sujeito a alteração</td></tr>`))}<p class="muted">As prévias não foram inseridas como novos débitos bancários. O pagamento de outubro do Mastercard já está realizado. Parcelamentos futuros e saldo desta fatura não são somados novamente.</p></article>`;
}
function auditView(){
 return `<h2>Validação dos arquivos</h2><article class="card"><div class="row"><span class="good">${state.checks.length} conferências aritméticas sem diferença</span><button id="restoreSources">Restaurar dados dos arquivos</button></div><p>Conferência de consistência interna dos documentos. A finalidade dos Pix, boletos e categorias sugeridas ainda depende da sua revisão.</p>${table(['Fonte','Conteúdo','Referência','Registros'],state.sources.map(s=>`<tr><td>${esc(s.file)}</td><td>${esc(s.kind)}</td><td>${esc(s.period)}</td><td>${s.records}</td></tr>`))}</article><article class="card"><h3>O que foi conferido e o que precisa de atenção</h3>${state.findings.map(f=>`<div class="finding"><b>${esc(f.title)}</b><p>${esc(f.text)}</p></div>`).join('')}</article><article class="card"><details><summary>Ver todas as conferências de saldo e total</summary>${table(['Conferência','Fonte','Informado','Calculado','Diferença'],state.checks.map(c=>`<tr><td>${esc(c.label)}</td><td>${esc(c.source)}</td><td class="num">${money(c.stated)}</td><td class="num">${money(c.computed)}</td><td class="num">${money(c.difference)}</td></tr>`),'checks')}</details><p class="muted">As conferências registram a importação original. Categorias e observações podem ser revistas sem alterar valores e descrições dos arquivos. Registros manuais são identificados à parte.</p></article>`;
}
function learningView(){
 const rules=state.recognitionRules||[],evidence=state.recognitionEvidence||[],confirmed=evidence.length,conflicts=rules.filter(r=>r.conflict).length;
 const manual=state.bankTransactions.filter(t=>t.categoryConfirmed),notesOnly=state.bankTransactions.filter(t=>t.note&&!t.categoryConfirmed);
 return `<h2>O que o sistema aprendeu</h2><div class="grid">${kpi('Revisões aproveitadas',num(confirmed),'Categorias confirmadas por você')}${kpi('Regras locais',num(rules.length),'Conta e cartões aprendem separadamente')}${kpi('Regras conflitantes',num(conflicts),'Conflitos impedem classificação automática')}</div><article class="card"><p>Suas revisões salvas neste navegador são analisadas ao abrir o protótipo e a cada nova revisão. Beneficiário, estabelecimento ou convênio identificável permitem reconhecer a categoria mesmo que a data e o valor mudem. O texto e as observações originais são preservados.</p><div class="note">Pix ou boletos com histórico genérico e sem beneficiário geram apenas sugestões. Valor igual não basta para confirmar a finalidade. Categorias reconhecidas ficam identificadas e podem ser corrigidas.</div>${table(['Identificação aprendida','Categoria','Como será usada','Revisões de origem'],rules.map(r=>`<tr><td>${esc(r.label)}<small>${r.ledger==='bank'?'Conta corrente':'Cartão'}</small></td><td>${esc(r.categories.join(' / '))}</td><td>${r.conflict?'Conflito: revisar, sem aplicação automática':r.strength==='automatic'?'Reconhecimento automático':'Sugestão; confirmar beneficiário'}</td><td>${r.evidenceCount}</td></tr>`))}</article><article class="card"><details><summary>Revisões da conta analisadas pelo sistema (${manual.length})</summary>${table(['Lançamento','Categoria confirmada','Sua observação'],manual.map(t=>`<tr><td>${br(t.date)} · ${esc(t.description)}<small>${money(t.value)}</small></td><td>${esc(t.category)}</td><td>${esc(t.note)||'—'}</td></tr>`))}</details>${notesOnly.length?`<p>${notesOnly.length} lançamentos têm observações, mas ainda estão sem categoria confirmada. As observações foram preservadas; não viraram regras de classificação.</p>`:''}<p class="muted">Aprendizado determinístico e local, sem envio de revisões à internet. As regras acompanham “Salvar cópia”. Restaurar os arquivos originais remove também as regras e revisões desta versão.</p></article>`;
}
let pendingBankImport=null;
document.getElementById('newStatementFile').addEventListener('change',async e=>{
 pendingBankImport=null;
 try{
  const file=e.target.files[0];if(!file)return;
  const incoming=JSON.parse(await file.text()),account=state.accounts[0];
  if(!Array.isArray(incoming.bankTransactions))throw Error('Use um arquivo JSON estruturado com bankTransactions. PDFs e planilhas precisam ser preparados antes da importação.');
  if(incoming.accountId!==account.id)throw Error('O arquivo deve identificar accountId como '+account.id+'.');
  const cutoff=incoming.asOf||state.asOf;
  if(!/^\d{4}-\d{2}-\d{2}$/.test(cutoff)||Number.isNaN(Date.parse(cutoff))||cutoff<state.asOf)throw Error('Data da posição inválida ou anterior à posição atual.');
  const rows=incoming.bankTransactions.map(t=>{
   if(!t.id||!/^\d{4}-\d{2}-\d{2}$/.test(t.date)||Number.isNaN(Date.parse(t.date))||t.date<=account.openingDate||typeof t.description!=='string'||!t.description.trim()||!Number.isFinite(t.value)||!Array.isArray(t.details)||t.details.some(d=>typeof d!=='string'))throw Error('Cada movimento precisa de id estável, data válida, descrição, valor numérico e detalhes.');
   return {...t,category:'A revisar',categoryConfirmed:false,categorySource:undefined,note:'',accountId:account.id,future:t.date>cutoff,source:{file:file.name},recognitionDisabled:false};
  });
  const trial=structuredClone(state),merged=FinanceCore.mergeRecords(trial.bankTransactions,rows);
  trial.bankTransactions=merged.records.sort((a,b)=>a.date.localeCompare(b.date));trial.asOf=cutoff;
  const learned=Recognition.refresh(trial);FinanceCore.validate(trial);
  pendingBankImport={trial,base:JSON.stringify(state)};
  document.getElementById('importSummary').innerHTML=`<p>${merged.added} novos lançamentos; ${merged.duplicates} já existentes, preservados com suas revisões.</p><p>Na base completa: ${learned.automatic} categorias reconhecidas e ${learned.suggestions} sugestões que exigem confirmação.</p><p>Posição: ${br(cutoff)}. Novo saldo próprio: ${money(FinanceCore.cashBalance(account,trial.bankTransactions,cutoff))}.</p><p class="muted">Somente conta corrente. Use identificadores estáveis da origem; pagamentos de fatura devem manter seu identificador bancário. Nenhuma compra de cartão será criada.</p>`;
  document.getElementById('importDialog').showModal();
 }catch(error){document.getElementById('message').textContent='Importação não realizada: '+error.message;}
 finally{e.target.value='';}
});
document.getElementById('confirmBankImport').addEventListener('click',()=>{
 if(!pendingBankImport)return;
 if(pendingBankImport.base!==JSON.stringify(state)){document.getElementById('message').textContent='Os dados mudaram. Selecione o arquivo para conferir novamente.';pendingBankImport=null;return;}
 state=pendingBankImport.trial;pendingBankImport=null;save();document.getElementById('importDialog').close();render();document.getElementById('message').textContent='Lançamentos importados; suas revisões e regras foram preservadas.';
});
function openReview(id,ledger){
 const t=(ledger==='bank'?state.bankTransactions:state.cardTransactions).find(t=>t.id===id);if(!t)return;
 editingRecord=t;document.getElementById('editDescription').textContent=t.description+' · '+money(t.value);
 document.getElementById('editCategory').innerHTML=categories.map(c=>`<option ${c===t.category?'selected':''}>${esc(c)}</option>`).join('');document.getElementById('editNote').value=t.note||'';document.getElementById('editDialog').showModal();
}
document.getElementById('editForm').addEventListener('submit',e=>{e.preventDefault();if(!editingRecord)return;delete editingRecord.categorySource;delete editingRecord.categoryBeforeRule;delete editingRecord.recognitionRule;editingRecord.category=document.getElementById('editCategory').value;editingRecord.recognitionDisabled=editingRecord.category==='A revisar';editingRecord.categoryConfirmed=editingRecord.category!=='A revisar';editingRecord.note=document.getElementById('editNote').value.trim();save();document.getElementById('editDialog').close();editingRecord=null;render();});
document.getElementById('addForm').addEventListener('submit',e=>{
 e.preventDefault();const values=Object.fromEntries(new FormData(e.target));const description=values.description.trim(),value=Number(values.value)*Number(values.direction);
 if(!description||!Number.isFinite(value)||!value||values.date<='2026-09-30'){alert('Confira a descrição, valor e data posterior a 30/09/2026.');return;}
 const transaction={id:'manual:'+crypto.randomUUID(),date:values.date,description,value,category:values.category,categoryConfirmed:values.category!=='A revisar',future:values.date>state.asOf,kind:'manual',details:['Registro manual, não consta no extrato importado.'],source:null};
 state.bankTransactions.push(transaction);state.bankTransactions.sort((a,b)=>a.date.localeCompare(b.date));save();document.getElementById('addDialog').close();e.target.reset();render();
});
document.addEventListener('click',e=>{
 const chartButton=e.target.closest('[data-chart-period]');if(chartButton){chartPeriod=chartButton.dataset.chartPeriod;render();return;}
 const tab=e.target.closest('[data-tab]');if(tab){go(tab.dataset.tab);return;}
 const review=e.target.closest('[data-review]');if(review){openReview(review.dataset.review,review.dataset.ledger);return;}
 if(e.target.id==='newStatement'){document.getElementById('newStatementFile').click();}
 if(e.target.id==='newBank'){document.getElementById('addCategory').innerHTML=categories.map(c=>`<option>${esc(c)}</option>`).join('');document.querySelector('#addForm [name=date]').value=state.asOf;document.getElementById('addDialog').showModal();}
 if(e.target.id==='restoreSources'&&confirm('Restaurar a importação original? Categorias revisadas, notas e registros manuais desta versão local serão removidos. Salve uma cópia antes de continuar.')){state=structuredClone(seedData);save();render();}
});
document.addEventListener('change',e=>{
 const id=e.target.id,value=e.target.value;
 if(id==='chartHorizon'){chartHorizon=Number(value);render();}
 else if(id==='chartFuture'){chartFuture=e.target.checked;render();}
 else if(id==='cardSelect'){cardId=value;holderFilter='';cardSearch='';render();}
 else if(id==='holderFilter'){holderFilter=value==='operations'?'operations':value;render();}
 else if(id==='bankMode'){bankMode=value;render();}
 else if(id==='investmentDate'){investmentDate=value;render();updateCDIView();}
});
document.getElementById('backupFile').addEventListener('change',async e=>{
 try{const file=e.target.files[0];if(!file)return;const parsed=JSON.parse(await file.text());FinanceCore.validate(parsed);if(!confirm('Substituir os dados desta versão local pela cópia selecionada?'))return;state=parsed;save();render();document.getElementById('message').textContent='Cópia carregada sem acrescentar lançamentos duplicados.';}
 catch(error){document.getElementById('message').textContent='Não foi possível carregar: '+error.message;}
 finally{e.target.value='';}
});
document.addEventListener('input',e=>{
 const id=e.target.id,value=e.target.value;
 if(!['bankSearch','cardSearch','investmentSearch'].includes(id))return;
 if(id==='bankSearch')bankSearch=value;if(id==='cardSearch')cardSearch=value;if(id==='investmentSearch')investmentSearch=value;
 const start=e.target.selectionStart;render();const next=document.getElementById(id);next.focus();next.setSelectionRange(start,start);updateCDIView();
});
function exportBackup(){
 const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='financas-familia-dados-locais.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('message').textContent='Cópia dos dados preparada para download.';
}
let cdi=null,cdiError=false;
function updateCDIView(){const value=document.getElementById('cdiValue'),ref=document.getElementById('cdiReference');if(!value)return;if(cdi){value.textContent=num(cdi.value)+'% a.a.';ref.textContent=(cdiError?'Consulta indisponível; última taxa salva':'Banco Central')+' · referência '+cdi.date;}else if(cdiError){value.textContent='Indisponível';ref.textContent='Não foi possível consultar o Banco Central.';}}
async function fetchCDI(){
 try{const cached=localStorage.getItem(storageKey+':cdi');if(cached)cdi=JSON.parse(cached);}catch(e){}
 updateCDIView();
 try{const r=await fetch('https://api.bcb.gov.br/dados/serie/bcdata.sgs.4389/dados/ultimos/1?formato=json',{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('Falha na consulta');const rows=await r.json(),last=rows.at(-1),value=Number(last.valor.replace(',','.'));if(!Number.isFinite(value)||value<=0||!/^\d{2}\/\d{2}\/\d{4}$/.test(last.data))throw Error('Taxa inválida');cdi={value,date:last.data};cdiError=false;try{localStorage.setItem(storageKey+':cdi',JSON.stringify(cdi));}catch(e){} }catch(e){cdiError=true;}updateCDIView();
}
const originalGo=go;go=function(tab){originalGo(tab);if(tab==='investments')updateCDIView();};
save();render();fetchCDI();
